// Tìm bài, kiểm tra trạng thái; nguon = 'duyet' (tự tạo khi duyệt) hoặc 'anhbia' (lệnh /anhbia)
const cmd = $('Khi được gọi').first().json;
const rows = $('Đọc lịch đăng').all().map(i => i.json);
const row = rows.find(r => String(r['ID']) === String(cmd.id));
if (!row) return [{ json: { ok: false, reply: `❌ Không tìm thấy bài #${cmd.id} trong lịch đăng.` } }];
const st = String(row['Trạng thái'] || '').trim();
if (!['Chờ duyệt', 'Chờ đăng'].includes(st))
  return [{ json: { ok: false, reply: `ℹ️ Bài #${row.ID} đang ở trạng thái "${st || 'trống'}" nên không tạo ảnh bìa (chỉ làm cho bài Chờ duyệt / Chờ đăng).` } }];
if (!row['Link ảnh']) return [{ json: { ok: false, reply: `❌ Bài #${row.ID} chưa có ảnh bài nên AI chưa làm được ảnh bìa.\n📎 Gửi ảnh vuông kèm /dunganh ${row.ID} (hoặc /anh ${row.ID}) trước, hoặc gửi luôn ảnh NGANG tự thiết kế kèm /dunganh ${row.ID} làm ảnh bìa.` } }];
const yc = String(cmd.request || '').trim();
return [{ json: { ok: true, id: String(row.ID), linkAnh: row['Link ảnh'], yc, oldBia: String(row['Ảnh bìa OA'] || '').trim(), nguon: cmd.nguon || 'duyet',
  ack: cmd.nguon === 'anhbia' ? `⏳ Đang tạo ảnh bìa Zalo OA cho bài #${row.ID}${yc ? ' theo yêu cầu: ' + yc : ''}… (khoảng 1 phút)` : '' } }];

const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const src = { mimeType: $input.first().binary.data.mimeType || 'image/jpeg', data: buf.toString('base64') };
const yc = String($('Chuẩn bị').first().json.yc || '').trim();
const prompt = "Image 1 is a finished SQUARE social-media poster. Redesign the SAME poster as a HORIZONTAL 16:9 landscape banner. Keep the same visual style, background colors, the big colored background shapes (for example a large orange circle or blob behind the headline), 3D illustration and every headline text with the same text colors, but re-arrange them for landscape: the label pill and the big headline lines on the LEFT half (large, bold, easy to read), the main illustration on the RIGHT half, background filling the whole frame seamlessly. Copy every Vietnamese text EXACTLY, character by character, with the correct diacritics; do not add, remove, translate or reword any text and do not add any new text, numbers, phone numbers, websites, watermarks or brand names. IMPORTANT: do NOT draw the GOS ACADEMY logo and do NOT draw the dark-red hotline bar from the bottom of image 1 - they will be added later. Leave the top-left corner area (left 22% of the width, top 20% of the height) as plain background with nothing in it, and leave the bottom 12% of the height as plain background with nothing in it. Keep all text and important objects at least 7% away from the left and right edges. Flat, clean, professional, high resolution." + (yc ? ' Extra request from the editor (follow it, but never change the texts): ' + yc : '');
const body = { contents: [{ parts: [{ inlineData: src }, { text: prompt }] }], generationConfig: { responseModalities: ['IMAGE'], imageConfig: { aspectRatio: '16:9' } } };
return [{ json: { src, body } }];

// Lấy ảnh ngang (ưu tiên model dự phòng nếu đã chạy) + logo + thanh hotline để ghép
const pick = (n) => { try { const j = $(n).first().json; return ((j.candidates || [])[0]?.content?.parts || []).find(p => p.inlineData && p.inlineData.data) || null; } catch (e) { return null; } };
const part = pick('Tạo ảnh ngang (dự phòng)') || pick('Tạo ảnh ngang (model rẻ)');
let kt = ''; try { const v = JSON.parse(($('Kiểm tra ảnh ngang').first().json.candidates[0].content.parts || []).map(p => p.text || '').join('')); kt = v.ok ? 'đạt' : v.loi; } catch (e) {}
if (!part) return [{ json: { coAnh: false, kt } }];
let model = 'gemini-3.1-flash-lite-image'; try { if ($('Tạo ảnh ngang (dự phòng)').isExecuted && pick('Tạo ảnh ngang (dự phòng)')) model = 'gemini-3-pro-image'; } catch (e) {}
const header = '';
const footer = '';
return [{ json: { coAnh: true, kt, model }, binary: {
  data: { data: part.inlineData.data, mimeType: part.inlineData.mimeType || 'image/png', fileName: 'bia.png' },
  header: { data: header, mimeType: 'image/png', fileName: 'header.png' },
  footer: { data: footer, mimeType: 'image/png', fileName: 'footer.png' } } }];

// Gửi ảnh bìa vào nhóm để xem trước (hoặc báo chưa tạo được)
const p = $('Chuẩn bị').first().json;
let url = ''; try { if ($('Lấy link ảnh bìa').isExecuted) url = (($('Lấy link ảnh bìa').first().json.images || []).sort((a, b) => b.width - a.width)[0] || {}).source || ''; } catch (e) {}
let att = null;
for (const nm of ['Zalo: tải ảnh bìa (thử lại)', 'Zalo: tải ảnh bìa']) { try { if (!att && $(nm).isExecuted) att = $(nm).first().json.data?.attachment_id || null; } catch (e) {} }
let kt = ''; try { kt = $('Lấy file ảnh ngang').first().json.kt || ''; } catch (e) {}
if (!url) return [{ json: { message: { text: `⚠️ Chưa tạo được ảnh bìa Zalo OA cho bài #${p.id}${kt && kt !== 'đạt' ? ' (' + kt + ')' : ''}.\nLúc đăng sẽ tạm dùng ảnh vuông đặt giữa nền mờ. Thử lại: /anhbia ${p.id} [yêu cầu]` } } }];
const text = `🖼 ẢNH BÌA ZALO OA – BÀI #${p.id}\nẢnh ngang 16:9, dùng làm ảnh đại diện khi bài được đăng lên Zalo OA.\nChưa ưng thì gõ: /anhbia ${p.id} <yêu cầu> (ví dụ: /anhbia ${p.id} chữ to hơn)\n↩️ Quay lại ảnh bìa trước: /hoantac ${p.id} bia\n✅ Ưng cả bài lẫn ảnh bìa thì gõ: /duyet ${p.id}`;
return [{ json: { message: att ? { text, attachment: { type: 'template', payload: { template_type: 'media', elements: [{ media_type: 'image', attachment_id: att }] } } } : { text: text + '\n🔗 ' + url } } }];
